--------------------------------------------------------
--  DDL for Index PK_CALL_REGISTERATION
--------------------------------------------------------

  CREATE UNIQUE INDEX "FAKHRUDDINERP"."PK_CALL_REGISTERATION" ON "FAKHRUDDINERP"."CALL_REGISTERATION" ("ID") 
  PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;
--------------------------------------------------------
--  DDL for Trigger CALL_PRE_APPROVE_TR
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "FAKHRUDDINERP"."CALL_PRE_APPROVE_TR" BEFORE  
  UPDATE OF APPROVE_STATUS ON CALL_REGISTERATION REFERENCING FOR EACH ROW
  DECLARE
   NSERIAL NUMBER;
BEGIN

IF :NEW.TR_TYPE <> 0 and :NEW.APPROVE_LEVEL <> 2 and :NEW.APPROVE_STATUS = 5 THEN
RAISE_APPLICATION_ERROR(-20100,'ONLY LEASING DEPARTMENT CAN PRE APPROVE');
END IF;

END CALL_PRE_APPROVE_TR;
/
ALTER TRIGGER "FAKHRUDDINERP"."CALL_PRE_APPROVE_TR" ENABLE;
--------------------------------------------------------
--  DDL for Trigger CALL_NO_CODE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "FAKHRUDDINERP"."CALL_NO_CODE" BEFORE INSERT OR UPDATE ON CALL_REGISTERATION REFERENCING FOR EACH ROW
DECLARE
CODE VARCHAR2(2000);
SN NUMBER DEFAULT 0;
BEGIN

SELECT COUNT(ID)+1 INTO SN FROM CALL_ESTIMATIONS WHERE HDR_ID = :NEW.ID;
:NEW.CALL_NO := ('QUO-'|| TO_CHAR(:NEW.FROM_DATE, 'DDMMYY')|| '-' || :NEW.ID || '-' || LPAD(SN, 2, '0'));

END CALL_NO_CODE;
/
ALTER TRIGGER "FAKHRUDDINERP"."CALL_NO_CODE" ENABLE;
